        "company": "델 테크놀로지스(Dell Technologies)는 컴퓨터·서버·저장장치를 만들어 파는 미국 컴퓨터 하드웨어 회사다. 원래는 노트북·데스크톱 PC(CSG 부문)를 기업과 개인에게 팔아 돈을 벌던 회사인데, 최근에는 엔비디아 GPU(그래픽처리장치)를 탑재한 인공지능(AI) 서버를 데이터센터 기업에 판매하는 사업(ISG 부문)이 훨씬 빠르게 커지고 있다. 주 고객은 대형 IT 기업, 클라우드·AI 인프라 구축업체, 그리고 일반 기업 고객이다. 최근에는 노르웨이에 AI 데이터센터를 짓는 스타트업 볼타(Volta)의 100억 달러(약 13조원) 규모 프로젝트에 기술 공급사로 선정되는 등 'AI 인프라 기업'으로 재평가받으며 주가가 올해 들어 크게 올랐다.",
        "lead": "델 테크놀로지스는 PC를 팔던 회사에서 AI 서버를 파는 회사로 빠르게 변신하고 있다. 5월 29일 발표한 2027회계연도 1분기 실적에서 매출이 438억 달러(전년 대비 +87.5%)로 컨센서스를 23.4% 웃돌았고, AI 서버 매출은 161억 달러(+757%)까지 치솟았다. 이 실적 발표 이후 8월 4일에는 노르웨이 AI 데이터센터에 100억 달러 규모 기술 공급사로 선정되며 주가가 하루 만에 8.92% 뛰어 사상 최고가를 경신했고, 8월 12일에는 종가 484.50달러로 다시 최고가를 갈아치웠다. 그 결과 주가는 올해 들어 260% 넘게 상승했다. 다만 이런 급등 이후 밸류에이션(주가 수준)이 이미 성장 기대를 상당 부분 반영했다는 우려와 메모리 가격 상승에 따른 마진 압박 우려도 함께 제기되고 있다.",
