        "leadOriginal": "진DX 홀딩스(GeneDx, WGS)는 신생아·소아 환자를 대상으로 유전자 전체를 읽어 희귀질환을 진단하는 유전체 검사 회사다. 2026년 8월3일 발표한 2분기 매출이 1억1,444만 달러로 전년 동기 대비 11% 늘며 자체 가이던스를 웃돌았고, 조정 EPS는 0.01달러로 컨센서스(-0.19달러 손실 예상)를 크게 뛰어넘어 서프라이즈 +105.26%를 기록했다. 엑솜·게놈 검사량은 분기 기준 최다인 3만785건(전년비 32%↑)을 기록했고, 조정 기준 흑자 전환도 시장 예상보다 한 분기 앞당겨졌다. 이후 8월19일 기준 한 달간 실적 전망치가 크게 상향되며 Zacks 등급이 최상위(Strong Buy)로 올라섰고, 이사회 멤버인 헤지펀드 대표 Eli Casdin의 대량 매수와 8월24일 발표된 소아 입원환자 대상 유전체 시퀀싱 연구 결과도 주가에 우호적으로 작용했다."
