        "company": "MP 머티리얼스는 미국 캘리포니아의 마운틴 패스(Mountain Pass) 광산에서 희토류(스마트폰·전기차 모터, 방위산업 무기체계에 들어가는 강력한 자석의 원료 광물)를 캐내 정제하고, 이를 최종적으로 자석(마그넷)으로 만들어 파는 회사다. '광산에서 자석까지(Mine-to-Magnet)'를 한 회사가 수직계열화해서 하겠다는 전략을 쓰고 있으며, 주요 고객은 미국 국방부(전쟁부로 개칭)와 애플·GM 같은 대기업, 그리고 최근에는 신규 항공우주·방위 업체까지 넓어지고 있다. 중국이 희토류 수출을 무기화하면서 미국이 자국 내 희토류 공급망을 새로 만들려는 움직임의 최전선에 있는 회사라서 최근 정치·경제적으로 크게 주목받고 있다. 미국 정부와 가격보호계약(PPA)을 맺어 NdPr(네오디뮴·프라세오디뮴) 산화물을 kg당 110달러에 사주기로 약속받아, 원자재 가격이 떨어져도 최소 수익을 보장받는 독특한 구조를 갖고 있다. 아직 분기 영업이익은 적자지만 매출은 빠르게 늘고 있어, 희토류·공급망 탈중국 테마의 대표주로 꼽힌다.",
        "ticker": "MP",
        "lead": "MP 머티리얼스는 미국 유일의 대규모 희토류(자석 원료 광물) 생산업체로, 마운틴 패스 광산에서 원료를 캐 정제하고 자석까지 만들어 파는 '광산-자석 일괄 생산' 전략을 펴고 있다. 8월 6일 발표한 2분기(4~6월) 매출이 1억850만 달러로 전년 대비 89% 늘었고, 6개월 누적 영업활동 현금흐름도 흑자로 돌아섰다. 같은 날 새로운 미국 항공우주·방위 고객과 분리 가돌리늄(gadolinium) 장기 공급계약을 새로 맺었다고 밝혔고, Materials(원료) 부문 상반기 매출은 80% 급증했다. 이런 실적 개선에 증권사들의 2026년 매출·이익 전망치도 상향 조정되며 최근 한 달 새 주가가 55.67% 급등했다.",
