              "date": "2026-01-21",
              "summary": "- 2026년 1월 미국 트럼프 행정부는 베네수엘라 석유 재건 사업을 전격 결정 및 관련 기업들에 투자 독려 중- 기존 베네수엘라→ 중국으로 판매되던 원유(40만배럴/일)이 미국 걸프만 지역으로 수출될 수 있어- 2026년 연초 미국의 베네수엘라 원유 수출 주도권 확보 및 재건 이후의 긍정적 효과를 고민해야할 시점",
