        "company": "시게이트 테크놀로지 홀딩스(Seagate Technology Holdings)는 컴퓨터나 데이터센터 안에 들어가는 하드디스크 드라이브(HDD, 데이터를 저장하는 원판형 저장장치)를 만들어 파는 회사입니다. 주 고객은 개인이 아니라 아마존·구글·마이크로소프트 같은 대형 클라우드 회사(하이퍼스케일러)로, 이들이 데이터센터에 대량으로 쌓아두는 '니어라인(nearline)' 서버용 대용량 HDD가 매출의 대부분을 차지합니다. 최근 주목받는 이유는 AI 열풍입니다 — AI 모델이 학습하고 만들어내는 데이터의 양이 폭발적으로 늘면서, 값싸게 대량 저장할 수 있는 HDD 수요가 다시 커지고 있습니다. 여기에 더해 시게이트는 'HAMR(레이저 열로 자기 기록 밀도를 높이는 신기술)'을 적용한 'Mozaic' 제품군으로 원판 하나에 더 많은 데이터를 담아 원가를 낮추면서 수익성을 크게 개선했고, 이 기술 전환 속도가 경쟁사보다 빠르다는 평가를 받고 있습니다. 그 결과 2026회계연도 4분기 실적이 시장 예상을 크게 웃돌았고, 주가는 연초 이후 200% 넘게 오르며 올해 미국 증시에서 가장 뜨거운 종목 중 하나가 됐습니다.",
