        "company": "레볼루션 메디신은 암세포를 계속 자라게 만드는 RAS 단백질의 돌연변이를 표적으로 삼는 먹는(경구용) 항암제를 개발하는 임상단계 바이오텍 기업이다. 지금까지는 상업화된 제품이 없어 분기 매출이 계속 0달러였지만, 2026년 8월 26일 대표 후보물질 다락소라십(daraxonrasib, 제품명 라소크·Rasonque)이 전이성 췌장암 치료제로 미국 FDA 승인을 받으면서 처음으로 매출을 낼 수 있는 상업화 단계에 들어섰다. 이 약은 30일 처방 기준 3만9,800달러로 가격이 책정됐으며, 주 고객은 병원·종양내과 의사와 마땅한 치료제가 없던 췌장암 등 난치암 환자들이다. RAS 변이는 췌장암, 폐암, 대장암 등 전체 암의 20% 이상에서 발견되는 만큼, 회사는 이 하나의 기술(삼중 복합체 플랫폼)로 여러 대형 암종을 동시에 공략하는 파이프라인을 확장하고 있다. 임상 3상에서 기존 화학요법 대비 생존기간을 거의 두 배로 늘린 데이터 덕분에 억만장자 투자자 스탠리 드러켄밀러를 비롯한 월가의 관심이 집중되며 최근 크게 주목받고 있다.",
