        "leadOriginal": "프레시펫은 8월 5일 발표한 2026회계연도 2분기 실적에서 매출 3억558만7천 달러(전년 대비 15.5% 증가)와 조정 주당순이익 0.39달러를 기록해 시장 예상치를 웃돌았다. 조정 EBITDA는 5,220만 달러로 전년 동기 4,440만 달러에서 늘었고, 조정 매출총이익률은 48.6%로 2020년 1분기 이후 최고치를 찍었다. 회사는 이를 근거로 2026년 매출 성장률 가이던스를 기존 8~11%에서 10~12%로, 조정 EBITDA 가이던스를 2억500만~2억1,500만 달러에서 2억1,000만~2억2,000만 달러로 올렸다. 실적 발표 직후 TD코웬·도이체방크·스티펠 등이 목표주가를 일제히 올렸지만, 바로 다음날인 8월 6일 모건스탠리는 밸류에이션 부담과 경쟁 심화를 이유로 투자의견을 '비중확대'에서 '중립'으로 낮췄고 주가도 6.4% 빠졌다."
