        "company": "실리콘모션테크놀로지(Silicon Motion)는 대만에 본사를 둔 반도체 설계회사로, 스마트폰·노트북·서버에 들어가는 낸드플래시 저장장치(SSD, eMMC, UFS 등)를 작동시키는 '컨트롤러 칩'을 설계해서 판다. 자체 공장 없이 설계만 하는 팹리스(fabless) 회사라, 실제 칩 생산은 위탁업체에 맡긴다. 주요 고객은 삼성전자·SK하이닉스·마이크론 같은 낸드 메모리 제조사와 이들의 낸드를 SSD로 조립하는 저장장치 업체들이다. 최근에는 자동차용 저장장치 브랜드 '페리(Ferri)'와 서버·데이터센터용 엔터프라이즈 SSD 컨트롤러 '몬티탄(MonTitan)'으로 사업을 넓히면서, AI 데이터센터 확장에 따른 고용량 스토리지 수요 증가의 수혜주로 주목받고 있다. 2026년 2분기 매출이 전년 동기 대비 127% 늘어나는 등 실적이 가파르게 개선되면서 주가도 함께 강하게 올랐다.",
        "lead": "실리콘모션(SIMO)은 2026년 7월 29일 발표한 2분기 실적에서 매출 4억5,100만 달러(전년 동기 1억9,870만 달러 대비 127% 증가)와 비-GAAP 주당순이익 2.43달러를 기록해 시장 컨센서스(2.13달러)를 크게 웃돌았고, 이 소식에 주가는 하루 만에 21% 넘게 급등했다. 자동차·엔터프라이즈용 부트드라이브(Ferri) 매출이 전년비 1,690%대까지 폭증하며 신사업이 본궤도에 올랐고, 회사는 3분기 매출 가이던스로 5억1,900만~5억4,100만 달러를 제시해 추가 성장을 예고했다. 이에 웨드부시가 목표주가를 230달러에서 400달러로(6월 23일), 서스쿼해나가 275달러에서 350달러로(7월 31일) 각각 올리는 등 월가의 목표주가 상향이 이어났고, 8월 17일 기준 평균 목표주가 368.4달러는 당시 주가 대비 37%의 상승 여력을 시사했다. 다만 8월 10일 8억 달러 규모의 전환사채 발행을 발표하면서 주가가 하루 만에 7.9% 빠지는 등 희석 우려도 함께 불거졌다.",
